mod runner { pub mod harness; }
use std::{env,process::Command,path::Path};
fn main(){let mut mode="filter".to_string();let(mut image,mut qemu,mut root)=(None,"qemu-system-aarch64".to_string(),None);let mut a=env::args().skip(1);while let Some(k)=a.next(){match k.as_str(){"--mode"=>mode=a.next().unwrap(),"--image"=>image=Some(a.next().unwrap()),"--qemu"=>qemu=a.next().unwrap(),"--root"=>root=Some(a.next().unwrap()),_=>{}}}let image=image.expect("--image");let fw=Command::new(&qemu).args(["-L","help"]).output().ok().and_then(|o|String::from_utf8(o.stdout).ok()).and_then(|s|s.split_whitespace().map(|d|format!("{d}/edk2-aarch64-code.fd")).find(|p|Path::new(p).exists())).unwrap_or_else(||"/opt/homebrew/opt/qemu/share/qemu/edk2-aarch64-code.fd".into());let mut q=vec![qemu,"-M".into(),"virt,gic-version=3,virtualization=off".into(),"-accel".into(),"hvf".into(),"-cpu".into(),"host".into(),"-m".into(),"8G".into(),"-smp".into(),"4".into(),"-drive".into(),format!("if=pflash,format=raw,readonly=on,file={fw}"),"-serial".into(),"stdio".into(),"-display".into(),"none".into()];if image.ends_with(".iso"){q.extend(["-cdrom".into(),image])}else{q.extend(["-drive".into(),format!("if=none,format=raw,readonly=on,file={image},id=sporeesp"),"-device".into(),"virtio-blk-device,drive=sporeesp,bootindex=0".into()])}if let Some(r)=root{q.extend(["-drive".into(),format!("if=none,format=raw,id=sporeroot,file={r}"),"-device".into(),"virtio-blk-device,drive=sporeroot".into()])}std::process::exit(runner::harness::run(q,&mode,false));}
